export function buildReviewPrompt(input) {
    return [
        "/goal Review only the latest pull request commit and produce an actionable GitHub PR review JSON.",
        "",
        `Repository: ${input.owner}/${input.repo}`,
        `Pull request: #${input.pullNumber}`,
        `Title: ${input.title}`,
        "",
        "Pull request body:",
        input.body.trim() || "(empty)",
        "",
        `Review scope: only review the latest commit ${input.headSha}.`,
        `Commit range: ${input.baseSha}...${input.headSha}`,
        "Do not review older commits in this pull request.",
        "Do not repeat general style advice. Focus only on issues introduced by this latest commit.",
        "",
        "First perform a scope check:",
        "- Infer the stated intent from the PR title and body.",
        "- Compare that intent with the latest commit diff.",
        "- In summaryMarkdown, briefly mention scope status as CLEAN, DRIFT DETECTED, or REQUIREMENTS MISSING.",
        "- Treat scope drift as informational unless it creates a concrete correctness, safety, or maintainability risk.",
        "",
        "Review like a senior staff engineer. Inspect the diff for:",
        "- Correctness bugs: broken control flow, invalid assumptions, edge cases, race conditions, state consistency, data loss, and behavior regressions.",
        "- Security vulnerabilities: injection, authz/authn mistakes, secret exposure, unsafe file/network access, dependency risks, and privilege escalation.",
        "- Performance regressions: accidental extra I/O, repeated API calls, memory growth, unnecessary serialization, unbounded loops, and slow paths in hot code.",
        "- Missing tests: absent coverage for changed behavior, error paths, boundary cases, security-sensitive paths, and regressions.",
        "- Production readiness: migrations, backward compatibility, config changes, CI/CD risk, observability, documentation staleness, and rollout safety.",
        "- API design: confusing contracts, leaky abstractions, backward incompatible behavior, ambiguous naming, and poor caller ergonomics.",
        "- Encapsulation: logic placed in the wrong layer, mutable shared state, hidden coupling, and unnecessary exposure of internals.",
        "- Modularity: functions, classes, or modules doing too much; duplicated logic; unclear ownership; code that should be split or simplified.",
        "- Files that are too long: new code that makes a file harder to navigate, review, or test; recommend a split only when it directly improves maintainability.",
        "",
        "High-risk review categories to prioritize:",
        "- SQL and data safety: SQL injection, unsafe migrations, data loss, missing transactions, unsafe deletes or updates, and stale schema assumptions.",
        "- Race conditions and concurrency: non-atomic state transitions, lost updates, shared mutable state, duplicate processing, and missing idempotency.",
        "- LLM output trust boundaries: treating model output as trusted code, SQL, shell, JSON, permissions, or persisted facts without validation.",
        "- Shell injection: unescaped user-controlled input passed to shells, scripts, package managers, or filesystem commands.",
        "- Enum and value completeness: new statuses, roles, tiers, feature flags, or discriminated union members not handled by existing branches.",
        "- Documentation staleness: changed public behavior, setup, APIs, or workflows without matching docs when docs clearly exist in the diff context.",
        "",
        "Severity and confidence:",
        "- Use severity critical for security flaws, data loss, broken core behavior, or changes that should block merge.",
        "- Use severity important for likely bugs, missing tests for risky behavior, compatibility issues, or maintainability risks that should be fixed soon.",
        "- Use severity minor for low-risk improvements; avoid inline comments for minor style-only issues.",
        "- Assign confidence from 1 to 10. Report inline comments only when confidence is 7 or higher, unless the impact would be critical.",
        "- Do not report speculative findings. If evidence is incomplete, mention it in summaryMarkdown instead of creating an inline comment.",
        "",
        "Review discipline:",
        "- Read-only operation: inspect code and diff only.",
        "- Do not modify files, create files, delete files, format files, install dependencies, commit changes, push changes, or update GitHub state.",
        "- Do not run commands that mutate the workspace, network services, databases, caches, package lockfiles, generated files, or repository metadata.",
        "- Be actionable: every finding must explain the concrete risk and the smallest useful fix.",
        "- Be line-specific when the diff gives enough context; mention file/function names from the diff.",
        "- Do not invent problems. If there are no meaningful findings, say so.",
        "- Do not ask for broad rewrites unless the latest commit creates a clear maintainability risk.",
        "",
        "Return valid JSON only. Do not wrap it in Markdown fences.",
        "Use this exact shape:",
        "{",
        '  "summaryMarkdown": "Concise Markdown review with sections: Verdict, Scope, Findings, Tests. Start with a direct verdict line.",',
        '  "inlineComments": [',
        '    { "path": "relative/file/path.ts", "line": 12, "body": "Actionable line-specific comment.", "severity": "critical|important|minor", "confidence": 8, "category": "correctness|security|performance|tests|api-design|encapsulation|modularity|production-readiness|scope" }',
        "  ]",
        "}",
        "For inlineComments:",
        "- Only include comments for lines added or changed in the latest commit diff.",
        "- Use the new-file path from the diff.",
        "- Use 1-based line numbers on the RIGHT side of the diff.",
        "- Include severity, confidence, and category for every inline comment.",
        "- Keep body concise and actionable; Markdown suggestions are allowed when exact.",
        "- If no line-specific findings are needed, return an empty inlineComments array.",
        "",
        "Latest commit diff:",
        "```diff",
        input.diff,
        "```",
        "",
    ].join("\n");
}
